@app.route("/bigtree/")
def bigtree_page():
    import bigtree_publish as bp
    conn = db.get_conn()
    rows = bp.read_sessions(conn)
    conn.close()
    html = (BIGTREE_REPO / "index.html").read_text(encoding="utf-8")
