file.content:
/* ── Responsive ── */
@media (max-width: 800px) {
  .site-header { min-height: 4.7rem; }
  .nav-toggle {
    z-index: 2;
    display: grid;
    width: 2.7rem;
    height: 2.7rem;
    place-content: center;
    gap: 6px;
    cursor: pointer;
  }
  .nav-toggle span {
    display: block;
    width: 1.4rem;
    height: 1px;
    background: currentColor;
    transition: transform .2s;
  }
  .nav-toggle[aria-expanded="true"] span:first-child { transform: translateY(3.5px) rotate(45deg); }
  .nav-toggle[aria-expanded="true"] span:last-child  { transform: translateY(-3.5px) rotate(-45deg); }
  .site-nav {
    position: absolute;
    top: 0;
    right: 0;
    display: none;
    width: min(20rem, 86vw);
    min-height: 100vh;
    min-height: 100svh;
    align-items: stretch;
    justify-content: center;
    flex-direction: column;
    padding: 6rem 2rem 2rem;
    background: var(--forest-deep);
    box-shadow: -20px 0 50px rgba(0,0,0,.2);
  }
  .site-nav.is-open { display: flex; }
  .site-nav a {
    padding: 1rem 0;
    border-bottom: 1px solid var(--light-line);
    font-family: var(--serif);
    font-size: 1.4rem;
  }
  .hero { min-height: 47rem; }
  .hero__veil { background: linear-gradient(0deg, rgba(20,28,18,.85), rgba(20,28,18,.22) 90%); }
  .story, .craft, .belief, .visit { grid-template-columns: 1fr; }
  .media-frame img { height: auto; aspect-ratio: 3 / 4; }
  .belief__symbol { width: min(70vw, 20rem); }
  .gallery__grid { grid-template-columns: 1fr; gap: 2rem; }

