file.content:
.registration {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  padding: 88px 0;
}

.registration .section-label { color: var(--warm); }
.registration .section-title { color: var(--fg-light); }

.reg-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  margin-top: 48px;
  align-items: start;
}

.reg-steps {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.reg-step {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}

.reg-step-num {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--accent);
  color: var(--fg-light);
  font-size: 0.85rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.reg-step-text strong {
  display: block;
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--fg-light);
  margin-bottom: 4px;
}

.reg-step-text span {
  font-size: 0.88rem;
  color: rgba(255,255,255,0.65);
  line-height: 1.6;
}

.bank-card {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: var(--radius);
  padding: 32px 28px;
  backdrop-filter: blur(4px);
}

.bank-card-title {
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--warm);
  text-transform: uppercase;
  margin-bottom: 20px;
}

.bank-rows {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.bank-row {
  display: flex;
  gap: 12px;
  align-items: baseline;
}

.bank-label {
  font-size: 0.82rem;
  color: rgba(255,255,255,0.55);
  white-space: nowrap;
  min-width: 72px;
}

.bank-value {
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--fg-light);
  letter-spacing: 0.02em;
}

.bank-value.highlight {
  color: var(--warm);
  font-size: 1.05rem;
  letter-spacing: 0.04em;
}

.bank-divider {
  height: 1px;
  background: rgba(255,255,255,0.12);
  margin: 8px 0;
}

input.old_string:
