  height: 1px;
  background: rgba(255,255,255,0.12);
  margin: 8px 0;
}

.session-cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin: 48px 0 8px;
}

.session-card {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: var(--radius);
  padding: 24px 26px;
}

.session-card-city {
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--fg-light);
  margin-bottom: 10px;
}

.session-card-row {
  font-size: 0.9rem;
  color: rgba(255,255,255,0.72);
  line-height: 1.8;
}

.session-card-row .early-bird {
  color: var(--warm);
  font-weight: 700;
}

