input.text:
const heroImageDiv = document.querySelector('.hero-image');
const img = document.querySelector('.hero-image img');
const after = getComputedStyle(document.querySelector('.hero-image'), '::after');
JSON.stringify({
  viewportWidth: window.innerWidth,
  heroImagePosition: getComputedStyle(heroImageDiv).position,
  heroImageRect: heroImageDiv.getBoundingClientRect(),
  imgOpacity: getComputedStyle(img).opacity,
  afterBg: after.backgroundColor || after.background,
  bodyScrollWidth: document.body.scrollWidth
})

